def detect_universality_classes(orbits, threshold=1e-4):
    n = len(orbits)
    labels = [-1] * n
    current_label = 0
    for i in range(n):
        if labels[i] >= 0: continue
        labels[i] = current_label
        for j in range(i + 1, n):
            if labels[j] >= 0: continue
            if np.linalg.norm(orbits[i][-1] - orbits[j][-1]) < threshold:
                labels[j] = current_label
        current_label += 1
    return labels

def compute_contraction_rate(coarsen, samples):
    max_ratio = 0.0
    for i in range(len(samples)):
        for j in range(i + 1, len(samples)):
            d_before = np.linalg.norm(samples[i] - samples[j])
            if d_before < 1e-15: continue
            d_after = np.linalg.norm(coarsen(samples[i]) - coarsen(samples[j]))
            max_ratio = max(max_ratio, d_after / d_before)
    return max_ratio
